example:
composition "Follow" { ample 1  tempo 100  master-seed 77 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

follow listen {
  band mid
  baseline off
  attack 60 ms
  release 700 ms
  from source.audio -> audio
}

synth pad {
  wave saw
  gain -12 dB
  from phrase.notes -> notes
}

volume padDuck {
  gain -11 dB * listen.level
  from pad.audio -> audio
}

mixer room {
  inputs 4
  from source.audio -> audio1
  from padDuck.audio -> audio2
}

master output {
  from room.audio -> audio
}
